//! `[build.minify]` output settings.

use serde::{Deserialize, Serialize};
use tola_config::Config;

/// Minification, before publication, of the HTML Typst compiles and of the CSS and JavaScript
/// files in `[assets]`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Config)]
#[serde(default)]
#[config(section = "build.minify")]
pub struct MinifyConfig {
    /// Minify HTML generated by Typst. Omit this setting to leave minification on.
    pub html: bool,

    /// Minify CSS from `[assets]` and inline `<style>` elements. If omitted, minify both.
    pub css: bool,

    /// Minify `.js` and `.mjs` files from `[assets]` and inline `<script>` elements,
    /// including modules. Omit this setting to leave minification on.
    pub javascript: bool,
}

impl Default for MinifyConfig {
    fn default() -> Self {
        Self {
            html: true,
            css: true,
            javascript: true,
        }
    }
}

impl MinifyConfig {
    /// What `tola help "[build.minify]"` adds under its table.
    pub const HELP: &'static str = r#"
All three settings default to `true`. To keep the generated HTML readable, add this to
`tola.toml`.

```toml
[build.minify]
html = false
```

In a site created with `tola init`, write `= Hello` in `content/index.typ`. Run
`tola build` from the site root and open `public/index.html` in a text editor to see
the indented HTML. CSS and JavaScript still use their own settings.
Use `tola build --minify=false` to turn off all three for one run.
`check`, `dev`, and `preview` read these settings too.

CSS and JavaScript minifiers keep license comments starting with `/*!`. If minification fails,
Tola warns and keeps the original content. Asset URLs with cache-busting use the hash of the
published bytes after minification. A `generate-outputs` hook handles minification for its own
files."#;
}
